fn remove_front(a: &Vec<i32>) -> Vec<i32> {
    // Since the input is guaranteed non-empty, a.len() >= 1,
    // so a.len() - 1 will not underflow.
    let n = a.len();
    let mut result = Vec::with_capacity(n - 1);
    // Copy all elements from index 1..n into the new vector
    for i in 1..n {
        result.push(a[i]);
    }
    result
}

